        f_LinkColorBlender = Td2dColorBlender.Create(aTime, LinkColor, aTargetLinkColor);
        if (f_LinkHColorBlender != null)
        {
            FreeAndNil(f_LinkHColorBlender);
        }
        f_LinkHColorBlender = Td2dColorBlender.Create(aTime, LinkHColor, aTargetLinkHColor);
        f_LinkColorBlender.Run();
        f_LinkHColorBlender.Run();
    }
    
    protected override void DoExecuteScriptOperator(in If2DSOperator aOp)
    {
        float l_Time;
    
        if (aOp.OpType == otColor)
        {
            if ((aOp.ParamCount == 1) | ((aOp.ParamCount == 2) & (aOp.pm_GetParams(1).GetValue <= 0)))
            {
                Color = CorrectColor(Trunc(aOp.pm_GetParams(0).GetValue));
            }
            else
            {
                if (aOp.ParamCount == 2)
                {
                    l_Time = (aOp.pm_GetParams(1).GetValue / 1000);
                    BlendColor(CorrectColor(Trunc(aOp.pm_GetParams(0).GetValue)), l_Time);
                    if (!aOp.IsAsync)
                    {
                        ScriptDelay = l_Time;
                    }
                }
                else
                {
                    if ((aOp.ParamCount == 3) | ((aOp.ParamCount == 4) & (aOp.pm_GetParams(3).GetValue <= 0)))
                    {
                        Color = CorrectColor(Trunc(aOp.pm_GetParams(0).GetValue));
                        LinkColor = CorrectColor(Trunc(aOp.pm_GetParams(1).GetValue));
                        LinkHColor = CorrectColor(Trunc(aOp.pm_GetParams(2).GetValue));
                    }
                    else
                    {
                        l_Time = (aOp.pm_GetParams(3).GetValue / 1000);
                        BlendColor(CorrectColor(Trunc(aOp.pm_GetParams(0).GetValue)), l_Time);
                        BlendLinkColors(CorrectColor(Trunc(aOp.pm_GetParams(1).GetValue)), CorrectColor(Trunc(aOp.pm_GetParams(2).GetValue)), l_Time);
                        if (!aOp.IsAsync)
                        {
                            ScriptDelay = l_Time;
                        }
                    }
                }
            }
        }
        else
        {
            base.DoExecuteScriptOperator(aOp);
        }
    }
    
