    {
        base.DoSetColor(aColor);
        if (f_StaticText.TextColor != aColor)
        {
            f_StaticText.TextColor = aColor;
            if ((f_StaticText.LinkColor & 0xFF000000) != (aColor & 0xFF000000))
            {
                f_StaticText.LinkColor = ((aColor & 0xFF000000) | (f_StaticText.LinkColor & 0x00FFFFFF));
            }
            if ((f_StaticText.LinkHColor & 0xFF000000) != (aColor & 0xFF000000))
            {
                f_StaticText.LinkHColor = ((aColor & 0xFF000000) | (f_StaticText.LinkHColor & 0x00FFFFFF));
