    public void Load(Td2dFiler aFiler)
    {
        base.Load(aFiler);
        aFiler();
    }
    
    protected override void Cleanup()
    {
        ClearRotationBlender();
        base.Cleanup();
    }
    
    public void BlendAngle(in float aDelta, float aTime)
    {
        ClearRotationBlender();
        f_RotSpeed = 0;
        f_RotationBlender = Td2dSimpleBlender.Create(aTime, Angle, (Angle + aDelta));
        f_RotationBlender.Run();
    }
    
    public void BlendScale(in float aTargetScale, float aTime)
    {
        ClearScaleBlender();
        f_ScaleBlender = Td2dSimpleBlender.Create(aTime, Scale, aTargetScale);
        f_ScaleBlender.Run();
    }
    
    protected void ClearRotationBlender()
    {
        if (f_RotationBlender != null)
        {
            FreeAndNil(f_RotationBlender);
        }
    }
    
    protected void ClearScaleBlender()
    {
        if (f_ScaleBlender != null)
        {
            FreeAndNil(f_ScaleBlender);
        }
    }
    
    protected override void DoExecuteScriptOperator(in If2DSOperator aOp)
    {
        float l_Time;
        float l_Value;
    
        switch (aOp.OpType)
        {
            case otRotate:
                l_Value = aOp.pm_GetParams(0).GetValue;
                if (!aOp.IsRelative)
                {
                    Angle = l_Value;
                }
                else
                {
                    if (aOp.ParamCount == 2)
                    {
                        l_Time = (aOp.pm_GetParams(1).GetValue / 1000);
                        BlendAngle(l_Value, l_Time);
                        if (!aOp.IsAsync)
                        {
                            ScriptDelay = l_Time;
                        }
                    }
                    else
                    {
                        Angle = (Angle + l_Value);
                    }
                }
                break;
            case otScale:
                l_Value = aOp.pm_GetParams(0).GetValue;
                if (aOp.ParamCount == 2)
                {
                    l_Time = (aOp.pm_GetParams(1).GetValue / 1000);
                    BlendScale(l_Value, l_Time);
                    if (!aOp.IsAsync)
                    {
                        ScriptDelay = l_Time;
                    }
                }
                else
                {
                    Scale = l_Value;
                }
                break;
            case otRotateSpeed:
                RotSpeed = aOp.pm_GetParams(0).GetValue;
                break;
            default:
                base.DoExecuteScriptOperator(aOp);
                break;
        }
    }
    
    private void pm_SetAngle(in float Value)
    {
        f_RotSpeed = 0;
        ClearRotationBlender();
        SetAnglePrim(Value);
    }
    
    protected virtual void pm_SetHotX(in int aHotX)
    {
        f_HotX = aHotX;
    }
    
    protected virtual void pm_SetHotY(in int aHotY)
    {
        f_HotY = aHotY;
    }
    
    private void pm_SetRotSpeed(in float Value)
    {
        ClearRotationBlender();
        f_RotSpeed = Value;
    }
    
    private void pm_SetScale(in float Value)
    {
        ClearScaleBlender();
        f_Scale = Value;
    }
    
    public override void Save(Td2dFiler aFiler)
    {
        bool l_NotNil;
    
        base.Save(aFiler);
        aFiler();
    }
    
    protected void SetAnglePrim(float aAngle)
    {
        f_Angle = aAngle;
        if ((f_Angle >= 360) | (f_Angle <= ( - 360)))
        {
            f_Angle = (f_Angle - (Int((f_Angle / 360)) * 360));
        }
        if (f_Angle < 0)
        {
            f_Angle = (360 + f_Angle);
        }
        f_AngleRad = (f_Angle * cPi180);
    }
    
    public override void Update(in float aDelta)
    {
        if (f_RotSpeed != 0)
        {
            SetAnglePrim((Angle + (f_RotSpeed * aDelta)));
        }
        if (f_RotationBlender != null)
        {
            f_RotationBlender.Update(aDelta);
            SetAnglePrim(f_RotationBlender.Current);
            if (!f_RotationBlender.IsRunning)
            {
                ClearRotationBlender();
            }
        }
        if (f_ScaleBlender != null)
        {
            f_ScaleBlender.Update(aDelta);
            f_Scale = f_ScaleBlender.Current;
            if (!f_ScaleBlender.IsRunning)
            {
                ClearScaleBlender();
            }
        }
        base.Update(aDelta);
    }
    
}

