public partial class Tf2ColoredDecorator
{
    public void Create(in float aPosX, in float aPosY, in float aPosZ, in uint aColor)
    {
        base.Create(aPosX, aPosY, aPosZ);
        f_Color = aColor;
    }
    
    public void Load(Td2dFiler aFiler)
    {
        base.Load(aFiler);
        aFiler();
    }
    
    public void BlendColor(in uint aTargetColor, in float aTime)
    {
        if (f_ColorBlender != null)
        {
            FreeAndNil(f_ColorBlender);
        }
        f_ColorBlender = Td2dColorBlender.Create(aTime, f_Color, aTargetColor);
        f_ColorBlender.Run();
    }
    
    protected override void Cleanup()
    {
        ClearColorBlender();
        base.Cleanup();
    }
    
    protected void ClearColorBlender()
    {
        if (f_ColorBlender != null)
        {
            FreeAndNil(f_ColorBlender);
        }
    }
    
    protected override void DoExecuteScriptOperator(in If2DSOperator aOp)
    {
        var __captured0_aOp = aOp;
        uint l_Color;
        int l_A;
        int l_R;
        int l_G;
        int l_B;
        float l_Time;
        int CorrectColorPart(in double aReal)
        {
            int __localResult1;
            __localResult1 = (Trunc(aReal) % 256);
            if (__localResult1 < 0)
            {
                __localResult1 = 0;
            }
            return __localResult1;
        }
    
    
        switch (aOp.OpType)
        {
            case otColor:
                l_Time = 0;
                if (aOp.ParamCount <= 2)
                {
                    l_Color = CorrectColor(Trunc(aOp.pm_GetParams(0).GetValue));
                    if (aOp.ParamCount == 2)
                    {
                        l_Time = (aOp.pm_GetParams(1).GetValue / 1000);
                    }
                }
                else
                {
                    l_A = CorrectColorPart(aOp.pm_GetParams(0).GetValue);
                    l_R = CorrectColorPart(aOp.pm_GetParams(1).GetValue);
                    l_G = CorrectColorPart(aOp.pm_GetParams(2).GetValue);
                    l_B = CorrectColorPart(aOp.pm_GetParams(3).GetValue);
                    l_Color = ARGB(l_A, l_R, l_G, l_B);
                    if (aOp.ParamCount == 5)
                    {
                        l_Time = (aOp.pm_GetParams(4).GetValue / 1000);
                    }
                }
                if (l_Time == 0)
                {
                    Color = l_Color;
                }
                else
                {
                    BlendColor(l_Color, l_Time);
                    if (!aOp.IsAsync)
                    {
                        ScriptDelay = l_Time;
                    }
                }
                break;
            default:
                base.DoExecuteScriptOperator(aOp);
                break;
        }
    }
    
    protected virtual void DoSetColor(uint aColor)
    {
        f_Color = aColor;
    }
    
    private void pm_SetColor(in uint Value)
    {
        ClearColorBlender();
        DoSetColor(Value);
    }
    
    public override void Save(Td2dFiler aFiler)
    {
        bool l_NotNil;
    
        base.Save(aFiler);
        aFiler();
    }
    
    public override void Update(in float aDelta)
    {
        UpdateColorBlending(aDelta);
        base.Update(in aDelta);
    }
    
    private void UpdateColorBlending(in float aDelta)
    {
        if (f_ColorBlender != null)
        {
            f_ColorBlender.Update(aDelta);
            DoSetColor(f_ColorBlender.Current);
            if (!f_ColorBlender.IsRunning)
            {
                FreeAndNil(f_ColorBlender);
            }
        }
    }
    
}

