        {
            if (D2DIsPointInRect(gD2DE.MouseX, gD2DE.MouseY, f_Rect))
            {
                if ((theEvent.EventType == INPUT_MBUTTONDOWN) & (theEvent.KeyCode == D2DK_LBUTTON))
                {
                    f_TargetProcessor.ExecuteAction(f_Rect, f_MenuAlign);
                    Processed(theEvent);
                }
                else
